# coding: utf-8
from save import *
save({
'A0797-B0097':'帝国部队曾三次进攻钢铁勇士的据点无眼巢穴。这里原是蓝宝石城下方的避难所，经改造后由庞大的隧道网络与其他被钢铁勇士占领的避难所相连，一直延伸至新月洋。第三次进攻与前两次一样失败了，连轨道轰炸也无法击穿它的防护。钢铁勇士试图歼灭已被击溃的帝国突击部队，帝国大巡洋舰梅洛克号却牺牲自身，挡住来自轨道的攻击，掩护友军。此后，帝国部队接连受挫：科巴莱克避难所莫名损失了四百台战争机器，卡西尔迪安山脉地堡因大气污染而陷落，新抵达的奎托斯军团又将泰坦与凯撒利安家族的骑士送上南半球。',
'A0797-B0099':'战事陷入长期消耗后，叛军与帝国都不肯认输，不断向塔兰的己方盟军输送军需。帝国之拳与钢铁之手派兵增援，其掠食者坦克在对抗叛军装甲部队时发挥了关键作用。超过一百万辆装甲载具在沙漠中厮杀，构成了帝国历史上规模最大的坦克会战。塔兰人很快意识到，自己无法在正面交战中匹敌叛变的星际战士，于是逐渐精通打了就跑的突袭与侧翼包抄，最终拖垮钢铁勇士，将其逐出行星。帝国还发起了针对罗格斯堡的反攻，主要由新近从太空抵达的极限战士援军领衔，最终夺回该城。不过，他们是在多次进攻之后才取得成功，死亡军团与一支叛变千子部队已给忠诚派造成惨重损失。',
'A0797-B0102':'第三次进攻无眼巢穴失败后，一场巨大的风暴笼罩大地，开始改变这里的一切。塔兰人将面貌一新的土地称为“亚森”，意为“迷失朝圣者之地”。随后，黄金舰队以鹰爪号为前导抵达。舰队由行商浪人桑格利亚统率，曾在大远征主力前方开路，麾下集合了雇佣兵与征服得来的舰船，包括圣物保管者吉内奥-赫特战士、克拉泽家族骑士，以及三百名极限战士。他们离开塔兰探索莫莱帷幕十年后，终于重返这里。黄金舰队刚进入星系，便向钢铁勇士声称自己是荷鲁斯的盟友，随即出其不意地袭击对方。抵达行星后，他们又拒绝接收帝国部队的任何消息，转而攻击一切试图向地表输送部队与物资的舰船。装有新星炮的战列巡洋舰被调到前方，追击供油船，用炮火点燃天空。这场袭击后来被称为“炼狱潮”。随后黄金舰队离去，使地表暂时摆脱了来自轨道的干预。',
'A0797-B0104':'佩图拉博派出蔑视者无畏机甲赫伦德，令其带领一支打击部队，在腐化导航员赫斯·塔尔的协助下搜寻地表的黑暗之眼。与此同时，阿尔戈尼斯在无眼巢穴的调查毫无进展，便拜访了当地核心区一号的钢铁勇士指挥官沃尔克，两人曾在卡梅林与雷德斯星群并肩作战。他们尚未谈出任何新线索，避难所上方的地表便遭到为进攻开路的轰炸，会面被迫中止。阿尔戈尼斯摆脱钢铁勇士守卫，来到避难所的数据存储区，索塔-努尔在其中查到了“黑暗之眼”这个名字。他们又前往索塔-努尔找到的另一处地点，途中阿尔戈尼斯被迫杀死一名钢铁勇士。抵达后，他们发现许多导航员被束缚起来，并注射了镇静剂。一行人唤醒其中一位女导航员，她解释了他们在恐惧之眼内经历的变化，以及黑暗之眼传送门的情况。众人离开房间时警报响起，很快便被捕入狱。',
'A0797-B0107':'军务总督德拉萨留斯竭力维持各部团结，不断推动进攻。双方援军持续涌入星系，战局却始终僵持不下。他将自己的战略称为“锋刃的纵深”，认为一次大规模突击便足以压垮钢铁勇士，将其逐出行星。然而，“炼狱潮”刚刚结束，他便遇刺身亡：从拉查布前往新月避难所的车队接近赫迪夫平原时，刺客从同行坦克连的一辆胜利者坦克上，向总督乘坐的毒刃开火。各部随即陷入分裂，直到戈恩将军接过指挥权，宣布唯一的取胜之道仍是进攻。帝国部队最终向赫迪夫平原发动全面攻势，将钢铁勇士引出无眼巢穴，展开决战。战斗先从太空打响：远程鱼雷击碎了无眼巢穴上方的钢铁勇士阵地，随后不屈打击部队发动大规模攻击。这为忠诚派争得了时间，使他们能在敌方反击前向地表出击。',
'A0797-B0111':'杰伦等阿尔法军团间谍的调查揭露了佩图拉博的目的：入侵塔兰、寻找黑暗之眼，从而以某种尚不明了的方式取得超越兄弟们的优势。在太空中，阿尔法军团释放荷鲁斯特使阿尔戈尼斯，企图借他迫使佩图拉博放弃追逐这股力量。阿尔戈尼斯却因这些特工仍在隐瞒秘密而将他们杀死，随后要求登上铁血号面见佩图拉博。与此同时，赫伦德发现黑暗之眼是一座传送门，能够让钢铁勇士与恶魔立约，获得力量。佩图拉博曾告诉他，这座门也叫阿尔加纳尔驰道，早在人类出现之前便已存在。赫伦德询问它的作用时，得到的回答是：它会改变钢铁勇士，赐予他们摧毁一切敌人的力量。赫伦德找到传送门所在，却遭遇阿尔法军团战士。他与同伴将对方全部杀死，己方战斗人员却只剩他勉强活了下来。他命令机仆杀死自己的导航员，再让机仆挖掘隧道，直达黑暗之眼，并在门前与一个恶魔相见。',
'A0797-B0113':'阿尔戈尼斯获准面见佩图拉博后，要求钢铁勇士放弃塔兰战役，却毫无结果，只得解开星语者普罗菲修斯身上的束缚。这位星语者经过改造，是一个“梅塔特隆”。束缚解除后，亚空间烟雾从他体内逸出，凝成荷鲁斯的形象，威胁并斥责擅自行事的钢铁勇士。荷鲁斯命令佩图拉博向自己跪下，随后撤出塔兰。赫伦德也未能完成原定任务：他拒绝屈服于恶魔的诱惑，反而启动自毁，将黑暗之眼重新掩埋。伊亚欧则耗尽最后的力量，阻止来自该地点的任何信息外传，确保它不会再被发现。',
'A0797-B0116':'战事结束后，新任军务总督苏萨达·辛与白疤的卡利高尔、戈恩将军一同乘坐最后一台泰坦，巡视这颗行星。毒云退去时，他们看见赫迪夫遍布坦克与各类机械的残骸，都是最后决战留下的遗迹。钢铁勇士同样损失惨重，佩图拉博被迫推行大规模征募，以补充兵员。',
'A0797-B0118':'这场战役在帝国历史上留下了长久的印记。自叛乱时代起，塔兰就一直是贫瘠的沙漠世界，其人民也始终坚韧、务实。从这里征募的帝国卫队兵团被称为“沙漠突袭者”，擅长沙漠作战与闪电突袭，其中也有帝国卫队最出色的一批坦克专家。',
'A0797-B0120':'此战的坦克会战规模在帝国历史上长期无出其右，直到 876.M41，帝国卫队与叛变的坚定愤怒泰坦军团交战，才出现足以与之相比的战斗。',
},[797],{
'A0797-B0097':'修正钢牙勇士为钢铁勇士。bunker fell 指地堡陷落，不是建筑坍塌。此处再称奎托斯军团“新抵达”，与前文已多次参战的叙述重复，保留原文。',
'A0797-B0099':'本段为战役概述，将撤军归于消耗与战术；后文详述荷鲁斯命令撤军及遗迹争夺。两种叙述层次一并保留，不删去后文政治因素。',
'A0797-B0102':'ahead of the Great Crusade 指在远征主力前方开路，不是发生在大远征之前。Sacristan Geneo-het warriors 的构词与身份未在所给英文中说明，Sacristan 暂沿核心“圣物保管者”，其余沿音译，待核；不擅补为骑士技师部队。黄金舰队拒收帝国消息且拦截一切地表运输，依原文保留。',
'A0797-B0104':'是被唤醒的女导航员解释自身经历，原译代词连接使说话人被误指为索塔-努尔。Black Occulus 为本段英文拼写变体，中文仍统一黑暗之眼。',
'A0797-B0107':'the depth of cutting edge 暂译“锋刃的纵深”，保留其作为战略称谓的地位，具体出处待核。刺客从坦克向总督的坦克开火，不是泛指持枪射击。末句 service 疑为 surface 的笔误，按本段太空战为地表攻击创造机会的语境译为地表。',
'A0797-B0111':'Cursus of Alganar 沿原有暂译“阿尔加纳尔驰道”，不可将 Cursus 当作 curse 译为诅咒。原文 joined by 在此随后发生交火，并非加入友军。赫伦德为战斗人员唯一幸存者，后文仍有机仆，译文保留两项信息。',
'A0797-B0113':'metatron 暂沿“梅塔特隆”，本篇只明确其为经改变的星语者及承载荷鲁斯显形的媒介，具体职衔性质待核。chastised 为斥责，并非已施以惩罚。',
'A0797-B0120':'Adamant Fury 为泰坦军团名称，暂沿原稿坚定愤怒，官方中文待核。',
})
replacements([797],{'叛軍':'叛军'})
terms=[('Infocyte','信息分析员','暂定·官方待核','所给英文底稿','A0797-B0010、B0095','原信息细胞特工；结合瓦努斯分支情报分析语境修订'),('Life-Eater Virus','噬生病毒','暂定·官方待核','所给英文底稿','A0793-B0033；A0797-B0045','原生命吞噬者病毒；全稿统一的描述性译名'),('Sightless Warren','无眼巢穴','暂定·官方待核','所给英文底稿','A0797-B0095—B0111','地下据点，非舰名；原无眼沃伦'),('Empyrean Coursers','至高天驰骋者','暂定·官方待核','所给英文底稿','A0797-B0075','自由之刃骑士队伍；Courser 非信使'),('Typhoeus','堤丰厄斯号','暂定·官方待核','所给英文底稿','A0797-B0083','战帅级泰坦名，区别 Typhus 人名提丰'),('Cursus of Alganar','阿尔加纳尔驰道','暂定·官方待核','所给英文底稿与主审统一决定','A0797-B0111','沿原稿，此为远古遗迹门户；Cursus 非 curse'),('Iydris','伊德瑞斯','暂定·官方待核','核心术语表529/102','A0797-B0030','依现核心地名统一；较早181战役名原伊德里斯之战待主审统一'),('the depth of cutting edge','锋刃的纵深','暂定·官方待核','所给英文底稿','A0797-B0107','德拉萨留斯作战方略称谓，意指大规模攻势；确切专名待核'),('Iaeo','伊亚欧','暂定·官方待核','所给英文底稿','A0797-B0095','瓦努斯分支女性信息分析员'),('Hrend','赫伦德','暂定·官方待核','所给英文底稿','A0797-B0104','钢铁勇士蔑视者无畏机甲'),('Hes-Thal','赫斯·塔尔','暂定·官方待核','所给英文底稿','A0797-B0104','腐化导航员'),('metatron','梅塔特隆','暂定·官方待核','所给英文底稿','A0797-B0113','用于普罗菲修斯的称谓；仅按原文，确切性质待核'),('Pi-East','派-东','暂定·官方待核','所给英文底稿','A0797-B0085','避难所名，原菲-西将字母和方向误译'),('Xi-South','克西-南','暂定·官方待核','所给英文底稿','A0797-B0085','避难所名，原希-南'),('Adamant Fury','坚定愤怒','暂定·官方待核','所给英文底稿','A0797-B0120','泰坦军团名称，沿原稿')]
